// FilterReason categorizes why a routing candidate was disqualified.
// The zero value (empty string) means the candidate is eligible.
type FilterReason string

const (
	// FilterReasonEligible is the zero value for an eligible candidate.
	FilterReasonEligible FilterReason = ""
	// FilterReasonContextTooSmall: candidate's context window is below the
	// request's MinContextWindow().
	FilterReasonContextTooSmall FilterReason = "context_too_small"
	// FilterReasonNoToolSupport: request needs tool calling but candidate
	// does not support it.
	FilterReasonNoToolSupport FilterReason = "no_tool_support"
	// FilterReasonReasoningUnsupported: candidate cannot satisfy the
	// requested reasoning policy.
	FilterReasonReasoningUnsupported FilterReason = "reasoning_unsupported"
	// FilterReasonUnhealthy: harness/provider is unavailable, in cooldown,
	// out of quota, or excluded by a hard provider-preference gate.
	FilterReasonUnhealthy FilterReason = "unhealthy"
	// FilterReasonScoredBelowTop: catch-all for ineligibility that does
	// not fit a more specific category (also used for capability
	// mismatches such as permissions/model-pin/exact-pin and for model
	// resolution failures).
	FilterReasonScoredBelowTop FilterReason = "scored_below_top"
	// FilterReasonPinMismatch: candidate was rejected because it does not
	// satisfy an explicit caller pin such as Provider.
	FilterReasonPinMismatch FilterReason = "pin_mismatch"
	// FilterReasonPowerMissing: automatic routing requires catalog power
	// metadata, but the candidate model is unknown or has zero power.
	FilterReasonPowerMissing FilterReason = "power_missing"
	// FilterReasonBelowMinPower: candidate model power is below req.MinPower.
	FilterReasonBelowMinPower FilterReason = "below_min_power"
	// FilterReasonAboveMaxPower: candidate model power is above req.MaxPower.
	FilterReasonAboveMaxPower FilterReason = "above_max_power"
	// FilterReasonExactPinOnly: catalog marks the model as only eligible for
	// explicit model pins.
	FilterReasonExactPinOnly FilterReason = "exact_pin_only"
	// FilterReasonNotAutoRoutable: catalog metadata exists but marks the
	// model inactive, deprecated, stale, or otherwise excluded from
	// automatic routing.
	FilterReasonNotAutoRoutable FilterReason = "not_auto_routable"
	// FilterReasonQuotaExhausted: provider is in the quota_exhausted state
	// with retry_after in the future. The candidate would have been eligible
	// otherwise.
	FilterReasonQuotaExhausted FilterReason = "quota_exhausted"
)

// NoViableCandidateError reports that routing evaluated candidates but every
// one failed a gate.
type NoViableCandidateError struct {
	Rejected int
	Model    string
	Provider string
	Harness  string
	MinPower int
	MaxPower int
}

func (e *NoViableCandidateError) Error() string {
	var pins []string
	if e.Model != "" {
		pins = append(pins, "model="+e.Model)
	}
	if e.Provider != "" {
		pins = append(pins, "provider="+e.Provider)
	}
	if e.Harness != "" {
		pins = append(pins, "harness="+e.Harness)
	}
	if e.MinPower > 0 {
		pins = append(pins, fmt.Sprintf("min_power=%d", e.MinPower))
	}
	if e.MaxPower > 0 {
		pins = append(pins, fmt.Sprintf("max_power=%d", e.MaxPower))
	}
	if len(pins) > 0 {
		return fmt.Sprintf("no viable routing candidate for pins %s: %d candidates rejected", strings.Join(pins, " "), e.Rejected)

		c.Providers[name] = normalized
	}

	c.validateProviders()

	if c.CompactionPercent != 0 && (c.CompactionPercent < 1 || c.CompactionPercent > 100) {
		return fmt.Errorf("config: compaction_percent must be 1-100, got %d", c.CompactionPercent)
	}

	return nil
}

func (c *Config) expandEndpointProviders() error {
	if len(c.Endpoints) == 0 {
		return nil
	}
	if c.Providers == nil {
		c.Providers = make(map[string]ProviderConfig, len(c.Endpoints))
	}
	firstGenerated := ""
	used := make(map[string]bool, len(c.Providers)+len(c.Endpoints))
	for name := range c.Providers {
		used[name] = true
	}
	for i, endpoint := range c.Endpoints {
		pc, name, err := providerConfigFromEndpoint(endpoint, i+1)
		if err != nil {
			c.addWarning(err.Error())
			continue
		}
		name = uniqueEndpointProviderName(name, used)
		used[name] = true
		c.Providers[name] = pc
		if firstGenerated == "" {
			firstGenerated = name
		}
	}
	if c.Default == "" && firstGenerated != "" {
		c.Default = firstGenerated
	}
	return nil
}

func providerConfigFromEndpoint(endpoint EndpointConfig, ordinal int) (ProviderConfig, string, error) {
	providerType := strings.ToLower(strings.TrimSpace(endpoint.Type))
	if providerType == "" {
		providerType = inferProviderTypeFromBaseURL(endpoint.BaseURL)
	}
	if providerType == "" {
		return ProviderConfig{}, "", fmt.Errorf("config: endpoint %d: type is required when base_url does not identify a provider", ordinal)
	}
	baseURL, err := endpointBaseURL(endpoint, providerType)
	if err != nil {
		return ProviderConfig{}, "", fmt.Errorf("config: endpoint %d: %w", ordinal, err)
	}
	name := strings.TrimSpace(endpoint.Name)
	if name == "" {
		name = generatedEndpointProviderName(endpoint, providerType, baseURL, ordinal)
	}
	return ProviderConfig{
		Type:    providerType,
		BaseURL: baseURL,
		Endpoints: []ProviderEndpoint{{
			Name:    "default",
			BaseURL: baseURL,
		}},
		APIKey:    endpoint.APIKey,
		Headers:   endpoint.Headers,
		Reasoning: endpoint.Reasoning,
	}, name, nil
}

func endpointBaseURL(endpoint EndpointConfig, providerType string) (string, error) {
	if baseURL := strings.TrimSpace(endpoint.BaseURL); baseURL != "" {
		return baseURL, nil
	}
	if providerType == "openrouter" {
		return openrouter.DefaultBaseURL, nil
	}
	host := strings.TrimSpace(endpoint.Host)
	if host == "" {
		return "", fmt.Errorf("host or base_url is required")
	}
	port := endpoint.Port
	if port == 0 {
		port = defaultEndpointPort(providerType)
	}
	if port == 0 {
		return "", fmt.Errorf("port is required for provider type %q", providerType)
	}
	if strings.HasPrefix(host, "http://") || strings.HasPrefix(host, "https://") {
		return strings.TrimRight(fmt.Sprintf("%s:%d", strings.TrimRight(host, "/"), port), "/") + "/v1", nil
	}
	return fmt.Sprintf("http://%s:%d/v1", host, port), nil
}

func defaultEndpointPort(providerType string) int {
	switch providerType {
	case "lmstudio":
		return 1234
	case "llama-server":
		return 8080
	case "omlx":
		return 1235
	case "lucebox":
		return 1236
	case "vllm":
		return 8000
	case "rapid-mlx":
		return 8000
	case "ollama":
		return 11434
	default:
		return 0
	}
}

func generatedEndpointProviderName(endpoint EndpointConfig, providerType, baseURL string, ordinal int) string {
	host := strings.TrimSpace(endpoint.Host)
	if host == "" {
		host = strings.TrimSpace(baseURL)
	}
	host = strings.NewReplacer("http://", "", "https://", "", "/v1", "", "/", "-", ":", "-").Replace(host)
	if host == "" {
		return fmt.Sprintf("%s-%d", providerType, ordinal)
	}
	if endpoint.Port > 0 {
		return fmt.Sprintf("%s-%s-%d", providerType, host, endpoint.Port)
	}
	return fmt.Sprintf("%s-%s", providerType, host)
}

func uniqueEndpointProviderName(name string, used map[string]bool) string {
	if !used[name] {
		return name
	}
	for i := 2; ; i++ {
		candidate := fmt.Sprintf("%s-%d", name, i)
		if !used[candidate] {
			return candidate
		}
	}
}

func normalizeProviderConfig(pc ProviderConfig) ProviderConfig {
	pc.Type = strings.ToLower(strings.TrimSpace(pc.Type))
	pc.BaseURL = strings.TrimSpace(pc.BaseURL)
	for i := range pc.Endpoints {
		pc.Endpoints[i].Name = strings.TrimSpace(pc.Endpoints[i].Name)
		pc.Endpoints[i].BaseURL = strings.TrimSpace(pc.Endpoints[i].BaseURL)
	}
	if pc.BaseURL == "" && len(pc.Endpoints) > 0 {
		pc.BaseURL = pc.Endpoints[0].BaseURL
	}
	if pc.Type == "" {
		pc.Type = inferProviderTypeFromBaseURL(pc.BaseURL)
	}
	switch pc.Type {
	case "openrouter":
		if pc.BaseURL == "" {
			pc.BaseURL = openrouter.DefaultBaseURL
		}
	case "openai":
		if pc.BaseURL == "" {
			pc.BaseURL = "https://api.openai.com/v1"
		}
	case "lmstudio":
		if pc.BaseURL == "" {
			pc.BaseURL = lmstudio.DefaultBaseURL
		}
	case "llama-server":
		if pc.BaseURL == "" {
			pc.BaseURL = llamaserver.DefaultBaseURL
		}
	case "omlx":
		if pc.BaseURL == "" {
			pc.BaseURL = omlx.DefaultBaseURL
		}
	case "lucebox":
		if pc.BaseURL == "" {
			pc.BaseURL = lucebox.DefaultBaseURL
		}
	case "vllm":
		if pc.BaseURL == "" {
			pc.BaseURL = vllm.DefaultBaseURL
		}
	case "rapid-mlx":
		if pc.BaseURL == "" {
			pc.BaseURL = rapidmlx.DefaultBaseURL
		}
	case "ollama":
		if pc.BaseURL == "" {
			pc.BaseURL = ollama.DefaultBaseURL
		}
	}
	if pc.BaseURL != "" && len(pc.Endpoints) == 0 && providerUsesEndpoint(pc.Type) {
		pc.Endpoints = []ProviderEndpoint{{Name: "default", BaseURL: pc.BaseURL}}
	}
	return pc
}

func inferProviderTypeFromBaseURL(baseURL string) string {
	baseURL = strings.TrimSpace(baseURL)
	if baseURL == "" {
		return ""
	}
	low := strings.ToLower(baseURL)
	switch {
	case strings.Contains(low, "openrouter.ai"):
		return "openrouter"
	case strings.Contains(low, "openai.com"):
		return "openai"
	case strings.Contains(low, "minimaxi.chat"):
		return "minimax"
	case strings.Contains(low, "dashscope.aliyuncs.com"):
		return "qwen"
	case strings.Contains(low, "z.ai"):
		return "zai"
	case strings.Contains(low, ":11434"):
		return "ollama"
	case strings.Contains(low, ":1234"):
		return "lmstudio"
	case strings.Contains(low, ":1235"):
		return "omlx"
	case strings.Contains(low, ":1236"):
		return "lucebox"
	case strings.Contains(low, ":8000"):
		return "vllm"
	default:
		return ""
	}
}

func providerUsesEndpoint(providerType string) bool {
	switch providerType {
	case "openai", "openrouter", "lmstudio", "llama-server", "omlx", "lucebox", "vllm", "rapid-mlx", "ollama", "minimax", "qwen", "zai":
		return true
	default:
		return false
	}
}

