package session

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"

	agent "github.com/DocumentDrivenDX/fizeau/internal/core"
)

// Replay reads a session log and renders a human-readable conversation.
func Replay(path string, w io.Writer) error {
	events, err := ReadEvents(path)
	if err != nil {
		return fmt.Errorf("replay: %w", err)
	}

	for _, e := range events {
		switch e.Type {
		case agent.EventLLMRequest:
			var data LLMRequestData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n[LLM Request] (%d messages, %d tools)\n", len(data.Messages), len(data.Tools))
			for _, m := range data.Messages {
				switch m.Role {
				case agent.RoleSystem:
					fmt.Fprintf(w, "  [system] %s\n", m.Content)
				case agent.RoleUser:
					fmt.Fprintf(w, "  [user] %s\n", m.Content)
				case agent.RoleAssistant:
					if m.Content != "" {
						fmt.Fprintf(w, "  [assistant] %s\n", m.Content)
					}
					for _, tc := range m.ToolCalls {
						fmt.Fprintf(w, "  [assistant tool_call] %s(%s)\n", tc.Name, compactJSON(tc.Arguments))
					}
				case agent.RoleTool:
					content := m.Content
					if len(content) > 200 {
						content = content[:200] + "...[truncated]"
					}
					fmt.Fprintf(w, "  [tool result] %s\n", strings.ReplaceAll(content, "\n", "\n              "))
				}
			}

		case agent.EventSessionStart:
			var data SessionStartData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "=== Session %s ===\n", e.SessionID)
			fmt.Fprintf(w, "Time: %s\n", e.Timestamp.Format("2006-01-02 15:04:05 UTC"))
			fmt.Fprintf(w, "Provider: %s | Model: %s\n", data.Provider, data.Model)
			if data.SelectedEndpoint != "" {
				fmt.Fprintf(w, "Selected endpoint: %s\n", data.SelectedEndpoint)
			}
			if data.Sticky.KeyPresent || data.Sticky.Assignment != "" || data.Sticky.Reason != "" {
				fmt.Fprintf(w, "Sticky: key=%s assignment=%s",
					routingStickyLabel(data.Sticky.KeyPresent),
					labelOrUnknown(data.Sticky.Assignment))
				if data.Sticky.Reason != "" {
					fmt.Fprintf(w, " reason=%s", data.Sticky.Reason)
				}
				fmt.Fprintln(w)
			}
			if data.Utilization.Source != "" || data.Utilization.Freshness != "" ||
				data.Utilization.ActiveRequests != nil || data.Utilization.QueuedRequests != nil ||
				data.Utilization.MaxConcurrency != nil || data.Utilization.CachePressure != nil {
				fmt.Fprintf(w, "Utilization: source=%s freshness=%s",
					labelOrUnknown(data.Utilization.Source),
					labelOrUnknown(data.Utilization.Freshness))
				if data.Utilization.ActiveRequests != nil {
					fmt.Fprintf(w, " active=%d", *data.Utilization.ActiveRequests)
				}
				if data.Utilization.QueuedRequests != nil {
					fmt.Fprintf(w, " queued=%d", *data.Utilization.QueuedRequests)
				}
				if data.Utilization.MaxConcurrency != nil {
					fmt.Fprintf(w, " max=%d", *data.Utilization.MaxConcurrency)
				}
				if data.Utilization.CachePressure != nil {
					fmt.Fprintf(w, " cache_pressure=%.2f", *data.Utilization.CachePressure)
				}
				fmt.Fprintln(w)
			}
			fmt.Fprintf(w, "Max iterations: %d | Work dir: %s\n", data.MaxIterations, data.WorkDir)
			if data.SystemPrompt != "" {
				fmt.Fprintf(w, "\n[System]\n%s\n", data.SystemPrompt)
			}
			fmt.Fprintf(w, "\n[User]\n%s\n", data.Prompt)

		case agent.EventLLMResponse:
			var data LLMResponseData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n[Assistant] (%dms, %d in / %d out tokens",
				data.LatencyMs, data.Usage.Input, data.Usage.Output)
			if data.CostUSD > 0 {
				fmt.Fprintf(w, ", $%.4f", data.CostUSD)
			}
			fmt.Fprintf(w, ")\n")
			if data.Content != "" {
				fmt.Fprintf(w, "%s\n", data.Content)
			}
			if len(data.ToolCalls) > 0 {
				fmt.Fprintf(w, "[%d tool call(s)]\n", len(data.ToolCalls))
			}

		case agent.EventToolCall:
			var data ToolCallData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n  > %s (%dms)\n", data.Tool, data.DurationMs)
			fmt.Fprintf(w, "    Input:  %s\n", compactJSON(data.Input))
			output := data.Output
			if len(output) > 200 {
				output = output[:200] + "...[truncated]"
			}
			fmt.Fprintf(w, "    Output: %s\n", strings.ReplaceAll(output, "\n", "\n            "))
			if data.Error != "" {
				fmt.Fprintf(w, "    Error:  %s\n", data.Error)
			}

		case agent.EventSessionEnd:
			var data SessionEndData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n=== End (%s) ===\n", data.Status)
			if data.Model != "" {
				fmt.Fprintf(w, "Model: %s\n", data.Model)
			}
			if data.SelectedEndpoint != "" {
				fmt.Fprintf(w, "Selected endpoint: %s\n", data.SelectedEndpoint)
			}
			fmt.Fprintf(w, "Duration: %dms | Tokens: %d in / %d out",
				data.DurationMs, data.Tokens.Input, data.Tokens.Output)
			if data.CostUSD == nil || *data.CostUSD < 0 {
				fmt.Fprintf(w, " | Cost: unknown")
			} else if *data.CostUSD > 0 {
				fmt.Fprintf(w, " | Cost: $%.4f", *data.CostUSD)
			} else {
				fmt.Fprintf(w, " | Cost: $0 (local)")
			}
			fmt.Fprintln(w)
			if len(data.Metadata) > 0 {
				fmt.Fprintf(w, "Metadata:")
				for k, v := range data.Metadata {
					fmt.Fprintf(w, " %s=%s", k, v)
				}
				fmt.Fprintln(w)
			}
			if data.Error != "" {
				fmt.Fprintf(w, "Error: %s\n", data.Error)
			}
		}
	}
	return nil
}

func routingStickyLabel(present bool) string {
	if present {
		return "present"
	}
	return "absent"
}

func labelOrUnknown(v string) string {
	if v == "" {
		return "unknown"
	}
	return v
}

func compactJSON(raw json.RawMessage) string {
	var v any
	if json.Unmarshal(raw, &v) != nil {
		return string(raw)
	}
	data, _ := json.Marshal(v)
	return string(data)
}

package fizeau

// This file implements ListProviders and HealthCheck for the FizeauService service.
// It lives in the root package to avoid import cycles; provider config data is
// injected via the ServiceConfig interface defined in service.go.
//
// Note: We cannot import agent/config or provider/openai here because both
// packages import the root agent package, creating a cycle. Provider probing
// is done inline using net/http.

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	claudeharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/claude"
	codexharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/codex"
)

const (
	defaultQuotaRefreshDebounce     = 15 * time.Minute
	defaultQuotaRefreshStartupWait  = 2 * time.Second
	defaultQuotaRefreshProbeTimeout = 30 * time.Second
)

// healthCheckClaudeQuotaRefresher is the function used to probe Claude's direct
// PTY quota. It is a package-level variable so tests can substitute a fake
// without spawning real harness sessions.
var healthCheckClaudeQuotaRefresher = func(timeout time.Duration) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
	return claudeharness.ReadClaudeQuotaViaPTY(timeout)
}

var healthCheckCodexQuotaRefresher = func(timeout time.Duration) ([]harnesses.QuotaWindow, error) {
	return codexharness.ReadCodexQuotaViaPTY(timeout)
}

var healthCheckCodexSessionQuotaReader = func() (*codexharness.CodexQuotaSnapshot, bool) {
	return codexharness.ReadCodexQuotaFromSessionTokenCounts()
}

var healthCheckQuotaProbeMu sync.RWMutex

var primaryQuotaRefresh = &quotaRefreshCoordinator{
	lastAttempt: make(map[string]time.Time),
	inFlight:    make(map[string]bool),
}

type quotaRefreshCoordinator struct {
	mu          sync.Mutex
	lastAttempt map[string]time.Time
	inFlight    map[string]bool
}

type quotaRefreshMode int

const (
	quotaRefreshAsync quotaRefreshMode = iota
	quotaRefreshStartup
)

type quotaRefreshPolicy struct {
	debounce     time.Duration
	startupWait  time.Duration
	probeTimeout time.Duration
}

type quotaCacheStatus struct {
	needsRefresh bool
	usable       bool
}

type providerProbeResult struct {
	status           string
	modelCount       int
	caps             []string
	detail           string
	endpointName     string
	baseURL          string
	endpointStatuses []EndpointStatus
}

func (s *service) ensurePrimaryQuotaRefresh(ctx context.Context, mode quotaRefreshMode) {
	policy := s.quotaRefreshPolicy()
	var waits []<-chan struct{}
	for _, name := range []string{"claude", "codex"} {
		status := primaryQuotaCacheStatus(name, policy.debounce)
		if !status.needsRefresh {
			continue
		}
		done := requestPrimaryQuotaRefresh(ctx, name, policy)
		if mode == quotaRefreshStartup && !status.usable && done != nil {
			waits = append(waits, done)
		}
	}
	if mode == quotaRefreshStartup && len(waits) > 0 && policy.startupWait > 0 {
		waitForPrimaryQuotaRefreshes(waits, policy.startupWait)
	}
}

func (s *service) quotaRefreshPolicy() quotaRefreshPolicy {
	policy := quotaRefreshPolicy{
		debounce:     defaultQuotaRefreshDebounce,
		startupWait:  defaultQuotaRefreshStartupWait,
		probeTimeout: defaultQuotaRefreshProbeTimeout,
	}
	if s != nil {
		if s.opts.QuotaRefreshDebounce > 0 {
			policy.debounce = s.opts.QuotaRefreshDebounce
		}
		if s.opts.QuotaRefreshStartupWait > 0 {
			policy.startupWait = s.opts.QuotaRefreshStartupWait
		}
	}
	return policy
}

func (s *service) startPrimaryQuotaRefreshWorker() {
	if s == nil || s.opts.QuotaRefreshInterval <= 0 {
		return
	}
	ctx := s.opts.QuotaRefreshContext
	if ctx == nil {
		ctx = context.Background()
	}
	interval := s.opts.QuotaRefreshInterval
	go func() {
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
			}
		}
	}()
}

func requestPrimaryQuotaRefresh(ctx context.Context, harnessName string, policy quotaRefreshPolicy) <-chan struct{} {
	done := make(chan struct{})
	if ctx == nil {
		ctx = context.Background()
	}
	if ctx.Err() != nil {
		close(done)
		return nil
	}

	now := time.Now()
	primaryQuotaRefresh.mu.Lock()
	if primaryQuotaRefresh.inFlight[harnessName] {
		primaryQuotaRefresh.mu.Unlock()
		close(done)
		return nil
	}
	if last := primaryQuotaRefresh.lastAttempt[harnessName]; !last.IsZero() && now.Sub(last) < policy.debounce {
		primaryQuotaRefresh.mu.Unlock()
		close(done)
		return nil
	}
	primaryQuotaRefresh.lastAttempt[harnessName] = now
	primaryQuotaRefresh.inFlight[harnessName] = true
	primaryQuotaRefresh.mu.Unlock()

	go func() {
		defer close(done)
		defer func() {
			primaryQuotaRefresh.mu.Lock()
			primaryQuotaRefresh.inFlight[harnessName] = false
			primaryQuotaRefresh.mu.Unlock()
		}()

		switch harnessName {
		case "claude":
			refreshClaudeQuotaCache(ctx, policy.debounce, policy.probeTimeout)
		case "codex":
			refreshCodexQuotaCache(ctx, policy.debounce, policy.probeTimeout)
		}
	}()
	return done
}

func waitForPrimaryQuotaRefreshes(waits []<-chan struct{}, timeout time.Duration) {
	deadline := time.After(timeout)
	for _, done := range waits {
		select {
		case <-done:
		case <-deadline:
			return
		}
	}
}

func primaryQuotaCacheStatus(harnessName string, debounce time.Duration) quotaCacheStatus {
	now := time.Now()
	switch harnessName {
	case "claude":
		cachePath, err := claudeharness.ClaudeQuotaCachePath()
		if err != nil {
			return quotaCacheStatus{}
		}
		snap, _ := claudeharness.ReadClaudeQuotaFrom(cachePath)
		if snap == nil {
			return quotaCacheStatus{needsRefresh: true}
		}
		decision := claudeharness.DecideClaudeQuotaRouting(snap, now, debounce)
		return quotaCacheStatus{
			needsRefresh: !decision.Fresh,
			usable:       decision.Fresh,
		}
	case "codex":
		cachePath, err := codexharness.CodexQuotaCachePath()
		if err != nil {
			return quotaCacheStatus{}
		}
		snap, _ := codexharness.ReadCodexQuotaFrom(cachePath)
		if snap == nil {
			return quotaCacheStatus{needsRefresh: true}
		}
		decision := codexharness.DecideCodexQuotaRouting(snap, now, debounce)
		return quotaCacheStatus{
			needsRefresh: !decision.Fresh || !codexQuotaCacheComplete(snap),
			usable:       decision.Fresh && decision.PreferCodex,
		}
	default:
		return quotaCacheStatus{}
	}
}

