// resolveModel picks the concrete model string for a (harness, provider) pair
// given the request. Returns the model and a non-empty rejection reason if
// resolution fails.
func resolveModel(h HarnessEntry, p ProviderEntry, req Request, in Inputs) (string, string) {
	// 1. Exact pin.
	if req.Model != "" {
		// If the provider has discovery data, try fuzzy matching to map the
		// canonical/short ref to the provider-native ID.
		if len(p.DiscoveredIDs) > 0 {
			if matched := FuzzyMatch(req.Model, p.DiscoveredIDs); matched != "" {
				return matched, ""
			}
			return "", fmt.Sprintf("model %q not on provider %q", req.Model, p.Name)
		}
		if p.DiscoveryAttempted {
			return "", fmt.Sprintf("provider %q has no live discovered models", p.Name)
		}
		return req.Model, ""
	}

	// 2. Catalog ref.
	if req.ModelRef != "" {
		if len(p.DiscoveredIDs) > 0 && in.CatalogCandidatesResolver != nil {
			if candidates, ok := in.CatalogCandidatesResolver(req.ModelRef, h.Surface); ok {
				for _, candidate := range candidates {
					if matched := FuzzyMatch(candidate, p.DiscoveredIDs); matched != "" {
						return matched, ""
					}
				}
				return "", fmt.Sprintf("model ref %q not on provider %q", req.ModelRef, p.Name)
			}
		}
		if in.CatalogResolver != nil {
			if concrete, ok := in.CatalogResolver(req.ModelRef, h.Surface); ok {
				// If discovery is available, double-check the concrete ID
				// (or the original ref) appears on this provider.
				if len(p.DiscoveredIDs) > 0 {
					if matched := FuzzyMatch(concrete, p.DiscoveredIDs); matched != "" {
						return matched, ""
					}
					// Try the original ref against discovery.
					if matched := FuzzyMatch(req.ModelRef, p.DiscoveredIDs); matched != "" {
						return matched, ""
					}
					return "", fmt.Sprintf("model ref %q not on provider %q", req.ModelRef, p.Name)
				}
				return concrete, ""
			}
			return "", fmt.Sprintf("model ref %q not available on surface %q", req.ModelRef, h.Surface)
		}
		if p.DiscoveryAttempted {
			return "", fmt.Sprintf("provider %q has no live discovered models", p.Name)
		}
		// No catalog: pass the ref through.
		return req.ModelRef, ""
	}

	// 3. Profile.
	if req.Profile != "" {
		if len(p.DiscoveredIDs) > 0 && in.CatalogCandidatesResolver != nil {
			if candidates, ok := in.CatalogCandidatesResolver(req.Profile, h.Surface); ok {
				for _, candidate := range candidates {
					if matched := FuzzyMatch(candidate, p.DiscoveredIDs); matched != "" {
						return matched, ""
					}
				}
				return "", fmt.Sprintf("profile %q has no candidate served by provider %q", req.Profile, p.Name)

package fizeau

import (
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

const stickyRouteLeaseTTL = routehealth.DefaultLeaseTTL

func (s *service) routeLeaseStore() *routehealth.LeaseStore {
	if s.routeLeases == nil {
		s.routeLeases = routehealth.NewLeaseStore()
	}
	return s.routeLeases
}

func (s *service) routeUtilizationStore() *routehealth.UtilizationStore {
	if s.routeUtilization == nil {
		s.routeUtilization = routehealth.NewUtilizationStore()
	}
	return s.routeUtilization
}

func (s *service) applyStickyRouteLease(stickyKey string, decision *RouteDecision) {
	if s == nil || decision == nil || strings.TrimSpace(stickyKey) == "" {
		return
	}
	decision.Sticky.KeyPresent = true
	if decision.Harness != "agent" || decision.Provider == "" {
		decision.Sticky.Assignment = "not_applicable"
		return
	}

	now := time.Now().UTC()
	store := s.routeLeaseStore()
	baseProvider, _, _ := splitEndpointProviderRef(decision.Provider)
	if baseProvider == "" {
		baseProvider = decision.Provider
	}
	if baseProvider == "" || decision.Model == "" {
		return
	}

	key := routehealth.NormalizeLeaseKey(stickyKey, baseProvider, decision.Model)
	if lease, ok := store.Live(now, key); ok {
		if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found && candidate.Eligible {
			store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, lease.Endpoint, decision.Model)
			decision.Provider = candidate.Provider
			decision.Endpoint = candidate.Endpoint
			decision.Sticky.Assignment = "reused"
			decision.Sticky.Reason = "live sticky lease reused"
			return
		}
		reason := "endpoint disappeared"
		if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found {
			reason = candidate.Reason
			if reason == "" {
				reason = "sticky endpoint became ineligible"
			}
		} else if candidate, found := stickyLeaseAnyEndpoint(decision.Candidates, decision.Harness, baseProvider, lease.Endpoint); found {
			reason = candidate.Reason
			if reason == "" {
				reason = "sticky endpoint became ineligible"
			}
		}
		store.Invalidate(now, key, reason)
	}
	if decision.Provider == "" && decision.Endpoint == "" {
		decision.Sticky.Assignment = "none"
		return
	}
	chosenEndpoint := decision.Endpoint
	if chosenEndpoint == "" {
		_, chosenEndpoint, _ = splitEndpointProviderRef(decision.Provider)
	}
	if chosenEndpoint == "" {
		chosenEndpoint = decision.Provider
	}
	if chosenEndpoint == "" {
		return
	}
	store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, chosenEndpoint, decision.Model)
	decision.Sticky.Assignment = "acquired"
	if decision.Sticky.Reason == "" {
		decision.Sticky.Reason = "new sticky lease acquired"
	}
}

func stickyLeaseCandidate(candidates []RouteCandidate, harness, provider, model, endpoint string) (RouteCandidate, bool) {
	for _, candidate := range candidates {
		if !candidate.Eligible || candidate.Harness != harness || candidate.Model != model {
			continue
		}
		baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		if candidateEndpoint == "" {
			candidateEndpoint = candidate.Endpoint
		}
		if candidateEndpoint == endpoint {
			return candidate, true
		}
	}
	return RouteCandidate{}, false
}

func stickyLeaseAnyEndpoint(candidates []RouteCandidate, harness, provider, endpoint string) (RouteCandidate, bool) {
	for _, candidate := range candidates {
		if candidate.Harness != harness {
			continue
		}
		baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		if candidateEndpoint == "" {
			candidateEndpoint = candidate.Endpoint
		}
		if candidateEndpoint == endpoint {
			return candidate, true
		}
	}
	return RouteCandidate{}, false
}

func (s *service) routeEndpointLoadsResolver(now time.Time) func(provider, endpoint, model string) (routing.EndpointLoad, bool) {
	if s == nil {
		return nil
	}
	leaseStore := s.routeLeaseStore()
	utilStore := s.routeUtilizationStore()
	return func(provider, endpoint, model string) (routing.EndpointLoad, bool) {
		leaseCounts := leaseStore.LeaseCounts(now, provider, model)
		loads := utilStore.EndpointLoads(provider, model, leaseCounts)
		load, ok := loads[endpoint]
		if !ok {
			if count, ok := leaseCounts[endpoint]; ok {
				return routing.EndpointLoad{
					LeaseCount:       count,
					NormalizedLoad:   float64(count),
					UtilizationFresh: false,
				}, true
			}
			return routing.EndpointLoad{}, false
		}
		return routing.EndpointLoad{
			LeaseCount:           load.LeaseCount,
			NormalizedLoad:       load.NormalizedLoad,
			UtilizationFresh:     load.UtilizationFresh,
			UtilizationSaturated: load.UtilizationSaturated,
		}, true
	}
}

	configuredDefaultModel := entry.Model
	providerType := normalizeServiceProviderType(entry.Type)

	outLen := 0
	for _, discovery := range discoveries {
		outLen += len(discovery.IDs)
	}
	out := make([]ModelInfo, 0, outLen)
	for _, discovery := range discoveries {
		// Build a position map from the ranked list.
		rankPos := make(map[string]int, len(discovery.Ranked))
		for pos, sm := range discovery.Ranked {
			rankPos[sm.ID] = pos
		}

		// Build CatalogRef map from ranked list.
		catalogRefMap := make(map[string]string, len(discovery.Ranked))
		for _, sm := range discovery.Ranked {
			if sm.CatalogRef != "" {
				catalogRefMap[sm.ID] = sm.CatalogRef
			}
		}

		for _, id := range discovery.IDs {
			info := ModelInfo{
				ID:              id,
				Provider:        providerName,
				ProviderType:    providerType,
				Harness:         "fiz",
				EndpointName:    discovery.EndpointName,
				EndpointBaseURL: discovery.EndpointBaseURL,
				Available:       true,
			}

			// Resolve context length: provider API > catalog > 0.
			info.ContextLength = resolveContextLength(ctx, entry, id, cat)

			// Capabilities from provider type.
			info.Capabilities = providerCapabilities(entry)

			// CatalogRef from ranked discovery.
			info.CatalogRef = catalogRefMap[id]

			// Cost and PerfSignal from catalog.
			if cat != nil && info.CatalogRef != "" {
				info.Cost, info.PerfSignal = catalogCostAndPerf(cat, id)
				info.Power, info.AutoRoutable, info.ExactPinOnly = catalogPowerEligibility(cat, id)
			} else if cat != nil {
				// Try direct model lookup by ID even without a catalog ref.
				info.Cost, info.PerfSignal = catalogCostAndPerf(cat, id)
				info.Power, info.AutoRoutable, info.ExactPinOnly = catalogPowerEligibility(cat, id)
			}

			// IsDefault: provider is default AND this model is the configured default model.
			info.IsDefault = isDefaultProvider && configuredDefaultModel != "" && id == configuredDefaultModel

			// RankPosition from discovery ranking.
			if pos, ok := rankPos[id]; ok {
				info.RankPosition = pos
			} else {
				info.RankPosition = -1
			}

			out = append(out, info)
		}
	}
	return out
}

type discoveredModelSet struct {
	EndpointName    string
	EndpointBaseURL string
	IDs             []string
	Ranked          []scoredModel
}

// discoverAndRankModels fetches the model list from each provider endpoint and
// ranks results against the catalog. IDs preserve discovery order per endpoint.
func discoverAndRankModels(ctx context.Context, entry ServiceProviderEntry, cat *modelcatalog.Catalog) []discoveredModelSet {
	switch normalizeServiceProviderType(entry.Type) {
	case "openai", "openrouter", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama", "minimax", "qwen", "zai":
		endpoints := modelDiscoveryEndpoints(entry)
		if len(endpoints) == 0 {
			return nil
		}
		out := make([]discoveredModelSet, 0, len(endpoints))
		for _, endpoint := range endpoints {
			ids, err := discoverModelsInline(ctx, endpoint.BaseURL, entry.APIKey)
			if err != nil || len(ids) == 0 {
				continue
			}
			out = append(out, discoveredModelSet{
				EndpointName:    endpoint.Name,
				EndpointBaseURL: endpoint.BaseURL,
				IDs:             ids,
				Ranked:          rankModelsInline(ids, cat),
			})
		}
		return out

	case "anthropic":
		// Anthropic does not expose /v1/models for discovery.
		// If a default model is configured, surface it.
		if entry.Model != "" {
			sm := scoredModel{ID: entry.Model, CatalogRef: "", RankPosition: 0}
			if cat != nil {
				if ref, ok := catalogRefForModel(cat, entry.Model); ok {
					sm.CatalogRef = ref
				}
			}
			return []discoveredModelSet{{
				EndpointName:    "default",
				EndpointBaseURL: entry.BaseURL,
				IDs:             []string{entry.Model},
				Ranked:          []scoredModel{sm},
			}}
		}
		return nil

	default:
		return nil
	}
}

type modelDiscoveryEndpoint struct {
	Name    string
	BaseURL string
}

func modelDiscoveryEndpoints(entry ServiceProviderEntry) []modelDiscoveryEndpoint {
	if len(entry.Endpoints) > 0 {
		out := make([]modelDiscoveryEndpoint, 0, len(entry.Endpoints))
		for _, ep := range entry.Endpoints {
			if strings.TrimSpace(ep.BaseURL) == "" {
				continue
			}
			out = append(out, modelDiscoveryEndpoint{
				Name:    endpointDisplayName(ep.Name, ep.BaseURL),
				BaseURL: ep.BaseURL,
			})
		}
		return out
	}
	if strings.TrimSpace(entry.BaseURL) == "" {
		return nil
	}
	return []modelDiscoveryEndpoint{{
		Name:    endpointDisplayName("default", entry.BaseURL),
		BaseURL: entry.BaseURL,
	}}
}

func endpointDisplayName(name, baseURL string) string {
	if trimmed := strings.TrimSpace(name); trimmed != "" {
		return trimmed
	}
	u, err := url.Parse(baseURL)
	if err == nil && u.Host != "" {
		return u.Host
	}
	return "default"
}

