// Discover checks which harnesses are available on the system.
func (r *Registry) Discover() []HarnessStatus {
	var statuses []HarnessStatus
	lookPath := r.LookPath
	if lookPath == nil {
		lookPath = DefaultLookPath
	}
	for _, name := range r.Names() {
		h := r.harnesses[name]
		status := HarnessStatus{
			Name:   name,
			Binary: h.Binary,
		}
		// Embedded harnesses are always available — no binary lookup needed.
		if name == "virtual" || name == "fiz" || name == "script" {
			status.Available = true
			status.Path = "(embedded)"
		} else if h.IsHTTPProvider {
			// HTTP-only providers: availability determined by probe, not binary.
			status.Available = true
			status.Path = "(http)"
		} else if path, err := lookPath(h.Binary); err != nil {
			status.Available = false
			status.Error = "binary not found"
		} else {
			status.Available = true
			status.Path = path
		}
		statuses = append(statuses, status)
	}
	return statuses
}

// FirstAvailable returns the first available harness in preference order.
func (r *Registry) FirstAvailable() (string, bool) {
	for _, s := range r.Discover() {
		if s.Available {
			return s.Name, true
		}
	}
	return "", false
}

package fizeau

import (
	"net/url"
	"strings"
)

// DeriveServerInstance returns the configured server instance when present.
// Otherwise it derives a stable identity from the base URL's host and port.
func DeriveServerInstance(baseURL, configured string) string {
	if v := strings.TrimSpace(configured); v != "" {
		return v
	}
	baseURL = strings.TrimSpace(baseURL)
	if baseURL == "" {
		return ""
	}
	if host, port, ok := parseURLHostPort(baseURL); ok {
		if port != "" {
			return host + ":" + port
		}
		return host
	}
	return baseURL
}

func parseURLHostPort(raw string) (host, port string, ok bool) {
	u, err := url.Parse(raw)
	if err == nil && u.Host != "" {
		host = strings.TrimSpace(u.Hostname())
		port = strings.TrimSpace(u.Port())
		if host != "" {
			return host, port, true
		}
	}
	if !strings.Contains(raw, "://") {
		u, err = url.Parse("http://" + raw)
		if err == nil && u.Host != "" {
			host = strings.TrimSpace(u.Hostname())
			port = strings.TrimSpace(u.Port())
			if host != "" {
				return host, port, true
			}
		}
	}
	return "", "", false
}

